            Tags = """["everywhere","lists","walkthrough"]""",
            ContentJson = """{"appRoute":"/parts","startButtonLabel":"Tour a List","steps":[{"element":"[data-testid='new-part-btn']","popover":{"title":"Every list looks like this","description":"Page actions such as New and Import sit at the top. The table below works the same way on every list page in Forge, so what you learn here applies everywhere.","side":"bottom"}},{"element":".data-table__th","popover":{"title":"Column headings","description":"Click a heading to sort. Click again to flip it. Hold Shift and click a second heading to sort within the first one. Drag the right edge of a heading to resize it.","side":"bottom"}},{"element":".data-table__col-menu-btn","popover":{"title":"The column menu","description":"The three dots on each heading open a menu with Sort, Filter, Hide Column and Reset Width. When a filter is active the button is tinted so you can see why rows are missing.","side":"bottom"}},{"element":".data-table__gear-btn","popover":{"title":"Export and columns","description":"Export CSV and Export Excel download exactly what you see — filtered, sorted, with your columns. The gear opens the column manager to show, hide and reorder columns. Forge remembers all of it for you.","side":"left"}}]}"""
