            ContentJson = """{"title":"Everywhere Quick Reference","groups":[{"heading":"Lists: sorting","items":[{"label":"Click a heading","value":"Sort ascending; click again for descending; a third click clears it."},{"label":"Shift + click","value":"Add a second (or third) sort column within the first."},{"label":"Drag a heading edge","value":"Resize the column. Reset Width in the column menu undoes it."}]},{"heading":"Lists: column menu (three dots on each heading)","items":[{"label":"Sort Ascending / Descending / Clear Sort","value":"Same as clicking the heading."},{"label":"Filter...","value":"Opens the filter for that column. The button is tinted with a dot while a filter is active."},{"label":"Clear Filter / Clear All Filters","value":"Remove this column's filter, or every filter on the list."},{"label":"Hide Column","value":"Hides the column. Bring it back with the gear button."}]},{"heading":"Lists: filter types","items":[{"label":"Text","value":"Match rule (Contains, Equals, Starts with, Ends with, Does not contain, Does not equal) plus a value."},{"label":"Number","value":"Min and Max; leave one blank for open-ended."},{"label":"Date","value":"From and To dates."},{"label":"Choice (Status and similar)","value":"Tick the values to keep."},{"label":"Apply / Clear","value":"Apply uses the filter; Clear removes it. Filters on several columns all have to pass."}]},{"heading":"Lists: top-right buttons","items":[{"label":"Export CSV","value":"Downloads the rows you can see, in your sort, with your visible columns."},{"label":"Export Excel","value":"The same, as an Excel workbook."},{"label":"Gear (Manage columns)","value":"Tick to show or hide; drag the handle to reorder; Reset restores the shipped layout."},{"label":"Remembered per list","value":"Sort, filters, column order, hidden columns, widths and page size are saved for you and only you."}]},{"heading":"Bulk actions (Job Board and Backlog)","items":[{"label":"Select on the Board","value":"Ctrl + click (Cmd + click on a Mac) each card."},{"label":"Select on the Backlog","value":"Tick row checkboxes, or the heading checkbox for the whole page."},{"label":"Move","value":"Send all selected jobs to a stage. Jobs that cannot make the move are reported, not silently skipped."},{"label":"Assign / Unassign","value":"Set one assignee on all selected jobs, or clear it."},{"label":"Priority","value":"Set the same priority on all selected jobs."},{"label":"Archive / Unarchive","value":"Archive from the Board (with a confirmation); restore from the Backlog."},{"label":"Clear selection","value":"Deselect without doing anything."}]},{"heading":"Attachments","items":[{"label":"Upload box","value":"Drag files onto it or click to browse. Several at once is fine."},{"label":"Size limit","value":"Shown in the box; set by your admin under Admin > Settings > Max Upload Size."},{"label":"Accepted types","value":"Shown in the box when the page restricts them. Typically PDF, images, Word, Excel; parts also take STEP, STL and DXF."},{"label":"Viewing","value":"Click a file: PDFs and images open in Forge, 3-D models open in a viewer, everything else downloads."}]},{"heading":"Import (Parts and Customers > Import)","items":[{"label":"Source","value":"Upload CSV or paste rows, then Parse. A header row is required."},{"label":"Preview","value":"Checks every row without saving. Statuses: Will create, Invalid, Duplicate in file, Already exists."},{"label":"Commit","value":"Saves only the Will create rows. Existing records are never updated by import."},{"label":"Reset","value":"Clears the page to start over."}]},{"heading":"CPA Exports (Accounting)","items":[{"label":"Range","value":"Date range for the export; presets for This Month and Last 30 Days."},{"label":"Files","value":"Trial Balance CSV, GL Detail CSV, Journal Summary CSV. One-way downloads."}]},{"heading":"Conflict dialogs","items":[{"label":"Record Changed","value":"Your save was refused because someone saved first. Reload discards your unsaved edits and fetches the latest; Cancel keeps your screen as is without saving."},{"label":"Sync Conflict","value":"A change queued while offline met a newer version. Keep Server drops yours; Keep Mine overwrites; Cancel leaves it queued."}]},{"heading":"Roles and landing","items":[{"label":"Missing button or menu","value":"Either your roles do not allow it (hidden, never greyed out) or the feature is switched off for the installation."},{"label":"Access denied","value":"The server refused an action your roles do not cover. Ask an admin for the role."},{"label":"Automatic landing","value":"Single-role users land on their role's home page; everyone else on the Dashboard."},{"label":"Landing screen","value":"Account > Customization. Pick a page or leave it on Automatic."},{"label":"Desktop preview popups","value":"Account > Customization. Turns the hover preview on record links on or off."}]}]}"""
