            Tags = """["everywhere","quiz"]""",
            ContentJson = """{"passingScore":80,"shuffleQuestions":false,"shuffleOptions":true,"showExplanationsAfterSubmit":true,"questions":[{"id":"q1","text":"You want the Sales Orders list sorted by customer, and within each customer by due date. How do you do it?","options":[{"id":"q1a","text":"Click Customer, then hold Shift and click Due Date","isCorrect":true},{"id":"q1b","text":"Click Customer, then click Due Date"},{"id":"q1c","text":"Export to Excel and sort there"},{"id":"q1d","text":"Ask an admin to change the default sort"}],"explanation":"A plain click replaces the sort. Shift + click adds a second sort column within the first."},{"id":"q2","text":"A coworker says the Parts list is missing rows that she can see on her screen. What is the most likely reason?","options":[{"id":"q2a","text":"You have a column filter active — look for a tinted three-dot button and use Clear All Filters","isCorrect":true},{"id":"q2b","text":"The parts were deleted"},{"id":"q2c","text":"Your Excel export is out of date"},{"id":"q2d","text":"Forge shows different parts to different roles"}],"explanation":"Filters, sort and column layout are remembered per user. A filter you set last week is still on, and the tinted column button shows where."},{"id":"q3","text":"What does Export CSV on a list include?","options":[{"id":"q3a","text":"Every record in the system, all columns"},{"id":"q3b","text":"The rows that pass your filters, in your sort, with the columns you have showing","isCorrect":true},{"id":"q3c","text":"Only the rows on the current page"},{"id":"q3d","text":"Only the columns that are sorted"}],"explanation":"Export gives you what you are looking at. Narrow and tidy the list first and the file needs no cleanup."},{"id":"q4","text":"On the Job Board you select ten jobs and use Move to send them to Assembly. Three of them are not allowed to make that move. What happens?","options":[{"id":"q4a","text":"Nothing moves until all ten can"},{"id":"q4b","text":"All ten are forced into Assembly"},{"id":"q4c","text":"Seven move and Forge tells you three could not","isCorrect":true},{"id":"q4d","text":"The three are archived"}],"explanation":"Bulk actions report per job. The ones that can change do, and the ones that cannot are counted in the message so you can handle them individually."},{"id":"q5","text":"After running Preview on a part import, a row shows Already exists. What happens to it when you click Commit?","options":[{"id":"q5a","text":"It is skipped; only Will create rows are saved","isCorrect":true},{"id":"q5b","text":"The existing part is updated with the row's values"},{"id":"q5c","text":"A second part with the same name is created"},{"id":"q5d","text":"The whole import is cancelled"}],"explanation":"Import creates new records and never updates existing ones. Duplicates and invalid rows are left alone and the final message shows how many went in."},{"id":"q6","text":"You click Save on a purchase order and see Record Changed: This record was changed by another user. Reload and try again? You click Reload. What happens to the edits you had not saved?","options":[{"id":"q6a","text":"They are merged with the other user's changes"},{"id":"q6b","text":"They are discarded and the latest version is loaded","isCorrect":true},{"id":"q6c","text":"They overwrite the other user's changes"},{"id":"q6d","text":"They are saved as a draft"}],"explanation":"Reload fetches the current record and drops your unsaved edits, so note what you changed first. Cancel keeps your screen as is without saving."},{"id":"q7","text":"A button your manager uses is not on your screen at all. What is the most likely reason?","options":[{"id":"q7a","text":"Your roles do not allow that action, so Forge hides the button rather than greying it out","isCorrect":true},{"id":"q7b","text":"Your browser window is too narrow"},{"id":"q7c","text":"The button only appears after you export the list"},{"id":"q7d","text":"You need to reload the page"}],"explanation":"Forge hides what your roles do not allow. If a feature is switched off for the installation it is hidden for everyone; otherwise ask an admin for the role."}]}"""
        });
    }
}
